import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a separable component (Rastrigin function)
    with a non-separable component (Rosenbrock function).  A linear term is also included.

    f(x) = Rastrigin(x) + Rosenbrock(x) + Linear(x)

    Args:
        x (np.ndarray): A 1D NumPy array of shape (N,) representing the input vector.

    Returns:
        float: The function value at the given input.
    """
    def rastrigin(x):
        """Rastrigin function"""
        n = len(x)
        return 10 * n + np.sum(x**2 - 10 * np.cos(2 * np.pi * x))

    def rosenbrock(x):
        """Rosenbrock function"""
        n = len(x)
        return np.sum(100 * (x[1:] - x[:-1]**2)**2 + (1 - x[:-1])**2)

    def linear(x):
        """Linear function"""
        return 0.01 * np.sum(x)

    return rastrigin(x) + 0.1 * rosenbrock(x) + linear(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a separable component (Weierstrass function)
    with a non-separable component (rotated quadratic).  A bias term is also included.

    f(x) = Weierstrass(x) + RotatedQuadratic(x) + Bias(x)

    Args:
        x (np.ndarray): A 1D NumPy array of shape (N,) representing the input vector.

    Returns:
        float: The function value at the given input.
    """
    def weierstrass(x):
        a = 0.5
        b = 3  #Lowered b from 3 to 2, should smooth the fitness
        k_max = 20
        result = 0.0
        for i in range(len(x)):
            for k in range(k_max + 1):
                result += (a**k) * np.cos(2 * np.pi * (b**k) * (x[i] + 0.5))
        return result

    def rotated_quadratic(x):
        n = len(x)
        Q = np.zeros((n, n))
        for i in range(n):
          for j in range(n):
            Q[i, j] = (i + j + 1) #Deterministic Q

        return 0.15 * np.dot(x.T, np.dot(Q, x)) #Scaling factor

    def bias(x):
        return 0.03 * np.sum(x) # Reduced bias

    return weierstrass(x) + rotated_quadratic(x) + bias(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a separable component (Weierstrass function)
    with a non-separable component (rotated quadratic).  A bias term is also included.

    f(x) = 0.8 * Weierstrass(x) + 0.1 * RotatedQuadratic(x) + Bias(x)

    Args:
        x (np.ndarray): A 1D NumPy array of shape (N,) representing the input vector.

    Returns:
        float: The function value at the given input.
    """
    def weierstrass(x):
        a = 0.5
        b = 3
        k_max = 20
        result = 0.0
        for i in range(len(x)):
            for k in range(k_max + 1):
                result += (a**k) * np.cos(2 * np.pi * (b**k) * (x[i] + 0.5))
        return result

    def rotated_quadratic(x):
        n = len(x)
        Q = np.zeros((n, n))
        for i in range(n):
                for j in range(n):
                    Q[i, j] = (i + j + 1)
        return np.dot(x.T, np.dot(Q, x))

    def bias(x):
        return 0.04 * np.sum(x)

    return 0.8 * weierstrass(x) + 0.1 * rotated_quadratic(x) + bias(x)

