import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a separable component (Weierstrass function)
    with a non-separable, deterministic quadratic component and a bias term.

    f(x) = Weierstrass(x) + DeterministicQuadratic(x) + Bias(x)

    Args:
        x (np.ndarray): A 1D NumPy array of shape (N,) representing the input vector.

    Returns:
        float: The function value at the given input.
    """
    def weierstrass(x):
        a = 0.5
        b = 3
        k_max = 20
        result = 0.0
        for i in range(len(x)):
            for k in range(k_max + 1):
                result += (a**k) * np.cos(2 * np.pi * (b**k) * (x[i] + 0.5))
        return result

    def deterministic_quadratic(x):
        n = len(x)
        # Create a fixed, symmetric matrix for deterministic behavior
        Q = np.eye(n)  # Start with an identity matrix
        for i in range(n):
            for j in range(n):
                Q[i, j] = 0.5 * (i + j)  # Introduce some interaction
        Q = np.dot(Q, Q.T)  # Guarantee positive semi-definiteness
        return 0.2 * np.dot(x.T, np.dot(Q, x)) # Scale it to control the influence

    def bias(x):
        return 0.05 * np.sum(x)

    return weierstrass(x) + deterministic_quadratic(x) + bias(x)
